let activeDeliveryTracker:{orderId:string;token:string}|null=null;
async function startNativeDeliveryTracking(orderId:string,token:string,onLocation?:(lat:number,lng:number)=>void){
  const base=(import.meta.env.VITE_SUPABASE_URL||'').replace(/\/$/,'');
  if(!base) throw new Error('Missing VITE_SUPABASE_URL');
  const url=`${base}/functions/v1/update-rider-location?order_id=${encodeURIComponent(orderId)}&token=${encodeURIComponent(token)}`;
  await BackgroundGeolocation.start({backgroundMessage:'YN Studio is sharing your location for this active delivery. Tracking stops when the delivery is complete.',backgroundTitle:'YN Studio delivery tracking',requestPermissions:true,stale:false,distanceFilter:20,url},(location:any,error:any)=>{
    if(error){console.warn('Background location',error);return}
    if(location?.latitude!=null&&location?.longitude!=null) onLocation?.(location.latitude,location.longitude);
  });
  activeDeliveryTracker={orderId,token};
}
async function stopNativeDeliveryTracking(){try{await BackgroundGeolocation.stop()}finally{activeDeliveryTracker=null}}
